#include "daxa_view_depth_common.hpp"
#include <daxa/c/device.h>
using namespace view_app;
int main(int argc,char** argv){try{
    if(getter(argc,argv))return 0;Options options(argc,argv,false);Prepared prepared(options);auto frames=options.u("--frames",30),warmup=options.u("--warmup",3);check(frames>=1&&frames<=300&&warmup<=30,"bounded frames1..300/warmup0..30 required");
    auto context=std::make_shared<DaxaFoundation>(options.validation);auto pipeline=std::make_unique<DaxaDepthPipeline>(prepared.fixture.rectification,prepared.depth,context,prepared.source);auto prototype=pipeline->enqueue(prepared.source);auto view=std::make_unique<DaxaView>(prepared.config,prepared.view,context,prototype,prepared.depth.slots);prototype={};pipeline->collect();
    VkPhysicalDeviceProperties properties{};vkGetPhysicalDeviceProperties(daxa_dvc_get_vk_physical_device(context->device.get()),&properties);double period=properties.limits.timestampPeriod;auto expected_view_bytes=view->allocated_bytes(),expected_depth_bytes=pipeline->requested_combined_buffer_bytes();check(expected_view_bytes+expected_depth_bytes<2ull*1024*1024*1024,"complete view-depth requested buffers exceed2GiB");std::array<std::vector<double>,7> samples;for(auto& a:samples)a.resize(frames);DaxaView::Frame output;
    for(uint32_t i=0;i<frames+warmup;++i){output={};auto start=Clock::now();bool available=view->can_project();pipeline->collect();check(available,"view capacity must precede upstream upload");auto input=pipeline->enqueue(prepared.source);output=view->project(input);auto submitted=Clock::now();output.wait();auto complete=Clock::now();auto depth_timing=input.timings();check(depth_timing.preprocessing.timestamp_period==period,"shared-context timestamp periods differ");double gpu_view=output.gpu_ms();auto begin_tick=depth_timing.preprocessing.start_tick,end_tick=output.end_tick();auto bits=depth_timing.preprocessing.timestamp_bits;auto mask=bits==64?UINT64_MAX:(uint64_t(1)<<bits)-1;double gpu_chain=double((end_tick-begin_tick)&mask)*period/1e6;auto queried=Clock::now();check(std::chrono::duration<long double,std::nano>(queried-start).count()<std::ldexp(static_cast<long double>(period),int(bits)),"chain timestamp wrap interval ambiguous");if(i>=warmup){unsigned j=i-warmup;std::array<double,7> values{std::chrono::duration<double,std::milli>(submitted-start).count(),std::chrono::duration<double,std::milli>(complete-submitted).count(),std::chrono::duration<double,std::milli>(queried-complete).count(),std::chrono::duration<double,std::milli>(queried-start).count(),gpu_chain,depth_timing.combined_gpu_ms,gpu_view};for(unsigned k=0;k<7;++k)samples[k][j]=values[k];}}
    check(view->allocated_bytes()==expected_view_bytes&&pipeline->requested_combined_buffer_bytes()==expected_depth_bytes,"resident chain buffers grew during measurement");auto diagnostic_start=Clock::now();GeometryReadback exported;if(options.values.contains("--dump-prefix")){exported=view->readback(output);dump(exported,options.values.at("--dump-prefix"));}double diagnostic_ms=std::chrono::duration<double,std::milli>(Clock::now()-diagnostic_start).count();auto result=report(prepared,false);if(options.values.contains("--dump-prefix"))coverage(result,exported);result["frames"]=frames;result["warmup"]=warmup;result["slots"]=prepared.depth.slots;result["disparities"]=prepared.depth.stereo.disparities;result["paths"]=prepared.depth.stereo.paths;result["required_wave_size"]=prepared.depth.required_wave_size;result["same_queue_chain_scope"]="upload_start_through_calibrated_view_end_including_intergraph_gaps";result["diagnostic_after_timing_ms"]=diagnostic_ms;result["requested_view_buffer_bytes"]=view->allocated_bytes();result["requested_chain_buffer_bytes"]=view->allocated_bytes()+pipeline->requested_combined_buffer_bytes();result["memory_scope"]="requested_buffers_only_excludes_driver_queries_diagnostics_CPU_source";constexpr const char* names[]={"enqueue_collect_cpu_ms","wait_cpu_ms","query_cpu_ms","host_wall_ms","gpu_chain_queue_span_ms","gpu_depth_queue_span_ms","gpu_view_ms"};for(unsigned k=0;k<7;++k)result[names[k]]=summary(samples[k]);output={};view->collect();view.reset();pipeline->drain();pipeline.reset();result["device"]=json::parse(context->report());context->close();check(context->validation_errors==0&&context->validation_warnings==0,"view-depth validation failed through teardown");result["validation_requested"]=options.validation;result["validation_errors_after_teardown"]=context->validation_errors.load();result["validation_warnings_after_teardown"]=context->validation_warnings.load();prepared.verify_inputs(options);finish(options,result);return 0;
}catch(std::exception const& e){std::cerr<<"daxa_view_depth_benchmark: "<<e.what()<<'\n';return 1;}}
